"""Exact local state snapshots. Load only snapshots generated by this project."""
import hashlib
import pickle
from pathlib import Path
from evolution import Simulation, FIELDS
import csv
import json

STREAMS = ('csv', 'records', 'events', 'births', 'learning')
NAMES = ('generations.csv', 'ancestry.jsonl', 'fruit_events.jsonl', 'births.jsonl', 'learning.jsonl')


def save_snapshot(path, simulations, manifest, publish):
    states = []
    for seed, mode, sim in simulations:
        sim.flush()
        state = {k: v for k, v in sim.__dict__.items() if k not in STREAMS and k != 'writer'}
        states.append((seed, mode, state))
    data = pickle.dumps(dict(version=1, manifest=dict(manifest), states=states), protocol=5)
    temporary = Path(str(path)+'.tmp')
    temporary.write_bytes(hashlib.sha256(data).hexdigest().encode()+b'\n'+data)
    publish(temporary, Path(path))


def load_snapshot(path, output):
    digest, data = Path(path).read_bytes().split(b'\n', 1)
    if hashlib.sha256(data).hexdigest().encode() != digest:
        raise ValueError('snapshot checksum mismatch')
    payload = pickle.loads(data)
    if payload['version'] != 1:
        raise ValueError('unsupported snapshot version')
    simulations = []
    for seed, mode, state in payload['states']:
        sim = Simulation.__new__(Simulation)
        sim.__dict__.update(state)
        sim.output = Path(output)/f'seed_{seed}_{mode}'
        sim.output.mkdir(parents=True, exist_ok=True)
        config = json.loads((Path(state['output'])/'config.json').read_text())
        config['output'] = str(sim.output)
        (sim.output/'config.json').write_text(json.dumps(config, indent=2))
        for key, name in zip(STREAMS, NAMES):
            setattr(sim, key, (sim.output/name).open('w', newline='', encoding='utf-8'))
        sim.writer = csv.DictWriter(sim.csv, fieldnames=FIELDS)
        sim.writer.writeheader()
        sim.closed = False
        simulations.append((seed, mode, sim))
    return payload['manifest'], simulations
